-			if (length != 0)
+			input_length = bk_mb_uart_read(MB_UART0, input, sizeof(input));
+			for (index = 0; index < input_length; index++)
 			{
-				if (bk_uart_write_bytes(UART_ID_0, buffer, length) != BK_OK)
